"""THE LOOK OF SCRUM MASTER 2, ONE PLACE (the owner 2026-11-03: "looks nothign like the origianl ... can you update the real one please"):
an agent writes SM2's own markup with SM2's own classes, and look.view() makes it a view the runtime passes (view.py's allowlist):
its table parts, labels and details become divs that keep their table display (t-table, t-tr, t-td ...), an id becomes a class (id-<name>),
a refused element (svg, textarea, a checkbox) or attribute is left out, and a form is a GET to the page itself. Its sheet is SM2's own
(SHEET: its canvas, live line, day, interface, the original's and the frame's sheets), its selectors rewritten the same way, and cut to
the rules the markup uses. The platform's own sheets (core.css, technology.css, the theme) are already in every view's shadow root."""
import html
import html.parser
import re

TAGS = frozenset('div span section article header footer p b strong i em small img button ul ol li h1 h2 h3 h4 h5 h6 br hr figure figcaption a canvas form input'.split())
AS_DIV = {'table': 't-table', 'thead': 't-thead', 'tbody': 't-tbody', 'tfoot': 't-tfoot', 'tr': 't-tr', 'th': 't-th', 'td': 't-td',
          'label': 't-label', 'details': 't-details', 'summary': 't-summary', 'nav': 't-nav', 'main': 't-main', 'aside': 't-aside',
          'code': 't-code', 'pre': 't-pre', 'colgroup': None, 'col': None}
INLINE = {'label', 'code'}
DROP = frozenset('svg path circle rect line polyline polygon g defs use script style link textarea select option iframe template'.split())
ATTRS = frozenset(('class', 'title', 'alt', 'role', 'type', 'src', 'loading', 'href', 'target', 'rel', 'method', 'action', 'name', 'value', 'placeholder'))
CASE = (':host-context(html[data-case="upper"]) * { text-transform: uppercase; } '   # THE PAGE'S LETTER CASE (its theme's html[data-case] rule), reaching inside the view
        ':host-context(html[data-case="mixed"]) * { text-transform: none; } '
        ':host-context(html[data-case="upper"]) :is(input, code, pre, [data-verbatim], [data-verbatim] *) { text-transform: none; }')
CARRY = ('site', 'mode', 'theme', 'agentlayer')   # THE PAGE'S OWN QUERY, kept by every press (its look and its layer)
BASE = ('.replica-live-line .scrum-since { margin-left: .4rem; } '   # SM2's counter, its space from its word (its page's sheet)
        '.t-table { display: table; border-collapse: collapse; } .t-thead { display: table-header-group; } .t-tbody { display: table-row-group; } '
        '.t-tfoot { display: table-footer-group; } .t-tr { display: table-row; } .t-th, .t-td { display: table-cell; } .t-th { font-weight: 700; } '
        '.t-label, .t-code { display: inline; } .t-pre { white-space: pre-wrap; } .t-summary { display: block; } .t-details { display: block; }')


class _Make(html.parser.HTMLParser):
    def __init__(self, path, carry=None):
        super().__init__(convert_charrefs=False)
        self.out, self.path, self.drop, self.stack = [], path, 0, []
        self.carry, self.form = dict(carry or {}), None

    def handle_starttag(self, tag, attrs, closed=False):
        if self.drop or tag in DROP:
            if tag not in ('path', 'circle', 'rect', 'line', 'polyline', 'polygon', 'use', 'link', 'col') and not closed:
                self.drop += 1
            return
        had = dict(attrs)
        cls = [c for c in (had.get('class') or '').split() if c]
        if had.get('id'):
            cls.append('id-' + re.sub(r'[^A-Za-z0-9_-]', '-', had['id']))
        name = tag
        if tag in AS_DIV:
            if AS_DIV[tag] is None:
                return
            cls.insert(0, AS_DIV[tag])
            name = 'span' if tag in INLINE else 'div'
        elif tag not in TAGS:
            name = 'div'
        if name == 'input' and (had.get('type') or 'text') not in ('text', 'hidden'):
            return
        keep = []
        for k, v in attrs:
            v = '' if v is None else v
            if k in ('class', 'id') or k.startswith('on') or k == 'style':
                continue
            if k == 'colspan':
                keep.append(('data-colspan', v))
            elif re.fullmatch(r'(data|aria)-[a-z0-9-]+', k):
                keep.append((k, v))
            elif k in ATTRS and self._fits(name, k, v, had):
                keep.append((k, v))
        if name == 'form':
            keep = [('method', 'get'), ('action', self.path)]
        if name == 'input' and not re.fullmatch(r'[a-z_]{1,32}', had.get('name', '') or ''):
            return
        if name == 'input':
            keep = [(k, v) for k, v in keep if k in ('type', 'name', 'value', 'placeholder')]
        if cls:
            keep.insert(0, ('class', ' '.join(dict.fromkeys(cls))))
        if name == 'form':
            self.form = set()
        if name == 'input' and self.form is not None:
            self.form.add(had.get('name', ''))
        text = '<' + name + ''.join(f' {k}="{html.escape(v, quote=True)}"' for k, v in keep) + '>'
        self.out.append(text)
        if not closed and name not in ('input', 'br', 'hr', 'img'):
            self.stack.append((tag, name))

    def _fits(self, name, k, v, had):
        if k in ('type',):
            return name == 'button' and v in ('button', 'submit') or name == 'input'
        if k in ('method', 'action'):
            return False
        if k in ('name', 'value', 'placeholder'):
            return name == 'input'
        if k in ('src', 'loading'):
            return name == 'img'
        if k in ('href', 'target', 'rel'):
            return name == 'a'
        return True

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs, closed=True)

    def handle_endtag(self, tag):
        if self.drop:
            if tag in DROP and tag not in ('path', 'circle', 'rect', 'line', 'polyline', 'polygon', 'use', 'link', 'col'):
                self.drop -= 1
            return
        if tag in DROP or AS_DIV.get(tag, 1) is None:
            return
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] == tag:
                if tag == 'form' and self.form is not None:
                    self.out.extend(f'<input type="hidden" name="{k}" value="{html.escape(str(v), quote=True)}">' for k, v in self.carry.items() if k not in self.form)
                    self.form = None
                for _t, name in reversed(self.stack[i:]):
                    self.out.append(f'</{name}>')
                del self.stack[i:]
                return

    def handle_data(self, data):
        if not self.drop:
            self.out.append(data)

    def handle_entityref(self, name):
        if not self.drop:
            self.out.append(f'&{name};')

    def handle_charref(self, name):
        if not self.drop:
            self.out.append(f'&#{name};')

    def close(self):
        super().close()
        for _t, name in reversed(self.stack):
            self.out.append(f'</{name}>')
        self.stack = []


def carried():
    """the page's own query this answer was handed (office.GIVEN page.search), the CARRY words alone, plain values"""
    try:
        import office
        search = ((office.GIVEN or {}).get('page') or {}).get('search') or {}
    except ImportError:
        search = {}
    return {k: str(search[k]) for k in CARRY if isinstance(search, dict) and re.fullmatch(r'[A-Za-z0-9_-]{1,64}', str(search.get(k) or ''))}


def markup(text, path, carry=None):
    """SM2's markup made a view's (see the module's words); path: the page's own path (a form's one address); carry: the page's own
    query every form keeps (carried() when none is given)"""
    m = _Make(path, carried() if carry is None else carry)
    m.feed(text)
    m.close()
    return ''.join(m.out)


_EL = re.compile(r'(?<![\w.#:-])(table|thead|tbody|tfoot|tr|th|td|label|details|summary|code|pre|nav|main|aside)(?![\w-])')


def _selector(sel):
    sel = re.sub(r'#([A-Za-z_][\w-]*)', lambda m: '.id-' + m.group(1), sel)
    return _EL.sub(lambda m: '.t-' + m.group(1), sel)


def _rules(sheet):
    """the sheet's rules, at-rules (media) kept whole: -> [(selector, body)]"""
    out, i, n = [], 0, len(sheet)
    while i < n:
        j = sheet.find('{', i)
        if j < 0:
            break
        head = sheet[i:j].strip()
        depth, k = 1, j + 1
        while k < n and depth:
            depth += {'{': 1, '}': -1}.get(sheet[k], 0)
            k += 1
        out.append((head, sheet[j + 1:k - 1]))
        i = k
    return out


def sheet_for(text, sheet):
    """the rules of sheet whose selectors the markup can match (every class and id they name is in it), rewritten as markup() writes"""
    sheet = re.sub(r'/\*.*?\*/', '', sheet, flags=re.S)   # comments out first: a comma inside one would cut it open
    used = set(re.findall(r'class="([^"]*)"', text))
    names = {c for group in used for c in group.split()}
    out = [BASE, CASE]
    for head, body in _rules(sheet):
        if head.startswith('@'):
            if head.startswith('@media'):
                inner = sheet_for(text, body).replace(BASE, '', 1).replace(CASE, '', 1).strip()
                if inner:
                    out.append(f'{head} {{ {inner} }}')
            elif head.startswith(('@keyframes', '@font-face')):
                continue
            continue
        keep = []
        for sel in head.split(','):
            sel = _selector(sel.strip())
            if not sel:
                continue
            need = set(re.findall(r'\.([A-Za-z_][\w-]*)', sel)) - {'t-' + t for t in AS_DIV}
            if need <= names:
                keep.append(sel)
        if keep:
            out.append(', '.join(keep) + ' { ' + body.strip() + ' }')
    return '\n'.join(out)


def view(text, path, extra=''):
    """SM2's markup and its sheet (SHEET, then extra: an agent's own few rules) as a view: {html, css}"""
    made = markup(text, path)
    return {'html': made, 'css': sheet_for(made, SHEET + '\n' + extra)}


